# SECTION 2: Price Distribution by Fuel Type
# ══════════════════════════════════════════════════════════════════════════
price_stats = df.groupby('fuel_type')['price_pence'].agg(
    count='count',
    mean='mean',
    median='median',
    std='std',
    min='min',
    max='max',
    q25=lambda x: x.quantile(0.25),
    q75=lambda x: x.quantile(0.75),
).sort_values('mean', ascending=False)

price_stats['iqr'] = price_stats['q75'] - price_stats['q25']
price_stats['range'] = price_stats['max'] - price_stats['min']

# ── Chart 1: Box plot of price distributions ──────────────────────────────
fig1, ax1 = plt.subplots(figsize=(10, 6))
fuel_order = price_stats.index.tolist()
box_data = [df[df['fuel_type'] == ft]['price_pence'].values for ft in fuel_order]
bp = ax1.boxplot(box_data, labels=fuel_order, patch_artist=True, showfliers=True,
                 flierprops=dict(marker='o', markersize=3, alpha=0.4),
                 medianprops=dict(color='black', linewidth=2))
for patch, ft in zip(bp['boxes'], fuel_order):
    patch.set_facecolor(fuel_color(ft))
    patch.set_alpha(0.7)
ax1.set_ylabel('Price (pence per litre)', fontsize=12)
ax1.set_title('Price Distribution by Fuel Type', fontsize=14, fontweight='bold', pad=15)
ax1.yaxis.set_major_formatter(mticker.FormatStrFormatter('%d'))
ax1.grid(axis='y', alpha=0.3)
fig1.tight_layout()
chart_boxplot = fig_to_base64(fig1)

