# ══════════════════════════════════════════════════════════════════════════
# SECTION 4: Retailer Reporting Freshness
# ══════════════════════════════════════════════════════════════════════════
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

lag_stats = df.groupby('fuel_type')['update_lag_hours'].agg(
    count='count',
    mean='mean',
    median='median',
    std='std',
    max='max',
    q75=lambda x: x.quantile(0.75),
    pct_over_24=lambda x: (x > 24).mean() * 100,
    pct_over_72=lambda x: (x > 72).mean() * 100,
).sort_values('median')

overall_lag_median = df['update_lag_hours'].median()
overall_lag_mean = df['update_lag_hours'].mean()
pct_over_24 = (df['update_lag_hours'] > 24).mean() * 100
pct_over_72 = (df['update_lag_hours'] > 72).mean() * 100
pct_negative = (df['update_lag_hours'] < 0).mean() * 100

# ── Chart 6: Update lag distribution ──────────────────────────────────────
fig6, ax6 = plt.subplots(figsize=(10, 5))
# Cap at 200 hours for visualization
lag_capped = df['update_lag_hours'].clip(upper=200)
lag_capped[lag_capped < -10] = np.nan
ax6.hist(lag_capped.dropna(), bins=80, color=COLORS['secondary'], alpha=0.8, edgecolor='white')
ax6.axvline(overall_lag_median, color=COLORS['accent'], linewidth=2, linestyle='--',
            label=f'Median: {overall_lag_median:.1f}h')
ax6.axvline(24, color='orange', linewidth=1.5, linestyle=':', label='24h threshold')
ax6.axvline(72, color='red', linewidth=1.5, linestyle=':', label='72h threshold')
ax6.set_xlabel('Update Lag (hours)', fontsize=12)
ax6.set_ylabel('Frequency', fontsize=12)
ax6.set_title('Distribution of Update Lag (recorded_at − source_updated_at)', fontsize=14, fontweight='bold', pad=15)
ax6.legend(fontsize=10)
ax6.grid(axis='y', alpha=0.3)
fig6.tight_layout()
chart_lag_hist = fig_to_base64(fig6)

# ── Chart 7: Lag by fuel type (box) ───────────────────────────────────────
fig7, ax7 = plt.subplots(figsize=(10, 6))
lag_fuel_order = lag_stats.index.tolist()
lag_box_data = [df[df['fuel_type'] == ft]['update_lag_hours'].clip(-10, 200).dropna().values
                for ft in lag_fuel_order]
bp7 = ax7.boxplot(lag_box_data, labels=lag_fuel_order, patch_artist=True, showfliers=False,
                   medianprops=dict(color='black', linewidth=2))
for patch, ft in zip(bp7['boxes'], lag_fuel_order):
    patch.set_facecolor(fuel_color(ft))
    patch.set_alpha(0.7)
ax7.axhline(24, color='orange', linewidth=1, linestyle=':', alpha=0.7, label='24h')
ax7.axhline(72, color='red', linewidth=1, linestyle=':', alpha=0.7, label='72h')
ax7.set_ylabel('Update Lag (hours)', fontsize=12)
ax7.set_title('Update Lag by Fuel Type (outliers hidden)', fontsize=14, fontweight='bold', pad=15)
ax7.legend()
ax7.grid(axis='y', alpha=0.3)
